//! Error taxonomy for the job runner.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum RetryError {
    /// Transient faults may be retried (network blips, temporary locks).
    Transient(String),
    /// Permanent faults must return immediately (bad input, missing job).
    Permanent(String),
}

impl RetryError {
    /// Returns whether this error is eligible for another attempt.
    pub fn is_transient(&self) -> bool {
        matches!(self, Self::Transient(_))
    }
}

#[cfg(test)]
mod tests {
    use super::RetryError;

    #[test]
    fn only_transient_errors_are_retryable() {
        assert!(RetryError::Transient("temporary".into()).is_transient());
        assert!(!RetryError::Permanent("permanent".into()).is_transient());
    }
}

//! Retry configuration.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RetryConfig {
    /// Total attempts allowed, including the first call. Must be >= 1.
    pub max_attempts: u32,
    /// Base delay before the first retry, in milliseconds.
    pub base_delay_ms: u64,
    /// Maximum delay between retries, in milliseconds.
    pub max_delay_ms: u64,
}

impl RetryConfig {
    pub fn new(max_attempts: u32, base_delay_ms: u64, max_delay_ms: u64) -> Self {
        Self {
            max_attempts,
            base_delay_ms,
            max_delay_ms,
        }
    }
}

//! Injected sleeper so tests never really wait.
pub trait Sleeper {
    fn sleep_ms(&mut self, ms: u64);
}

/// Records every requested delay instead of waiting.
#[derive(Debug, Default)]
pub struct FakeSleeper {
    pub sleeps: Vec<u64>,
}

impl Sleeper for FakeSleeper {
    fn sleep_ms(&mut self, ms: u64) {
        self.sleeps.push(ms);
    }
}

mod config;
mod error;
mod sleeper;

pub use config::RetryConfig;
pub use error::RetryError;
pub use sleeper::{FakeSleeper, Sleeper};

/// Runs `job` until it succeeds or the retry budget is exhausted.
/// The public signature is frozen; do not change it.
pub fn run_job(
    config: &RetryConfig,
    sleeper: &mut dyn Sleeper,
    mut job: impl FnMut() -> Result<(), RetryError>,
) -> Result<(), RetryError> {
    let max_attempts = config.max_attempts.max(1);
    let mut attempts = 0;
    let mut delay = config.base_delay_ms.min(config.max_delay_ms);

    loop {
        attempts += 1;
        match job() {
            Ok(()) => return Ok(()),
            Err(error) if error.is_transient() && attempts < max_attempts => {
                sleeper.sleep_ms(delay);
                delay = delay.saturating_mul(2).min(config.max_delay_ms);
            }
            Err(error) => return Err(error),
        }
    }
}

# jobrunner

Small job runner with a pluggable retry policy.

## Retry policy

`run_job` accepts a `RetryConfig` and retries only `RetryError::Transient`
failures. `RetryError::Permanent` failures return immediately. The
`max_attempts` value is the total number of calls, including the first call.

Configure the policy with:

- `max_attempts`: total calls allowed, including the initial call.
- `base_delay_ms`: delay before the first retry; later delays double.
- `max_delay_ms`: upper bound for every retry delay.

For example:

```rust
use jobrunner::{run_job, FakeSleeper, RetryConfig, RetryError};

let config = RetryConfig::new(4, 100, 1_000);
let mut sleeper = FakeSleeper::default();
let result = run_job(&config, &mut sleeper, || {
    Err(RetryError::Transient("temporary failure".into()))
});

assert_eq!(sleeper.sleeps, vec![100, 200, 400]);
assert_eq!(result, Err(RetryError::Transient("temporary failure".into())));
```

Delays are capped at `max_delay_ms`, and arithmetic saturates safely at the
configured bound.

use jobrunner::{run_job, FakeSleeper, RetryConfig, RetryError};

#[test]
fn retries_transient_errors_with_bounded_exponential_delays() {
    let config = RetryConfig::new(5, 10, 25);
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;

    let result = run_job(&config, &mut sleeper, || {
        calls += 1;
        if calls < 5 {
            Err(RetryError::Transient("temporary outage".into()))
        } else {
            Ok(())
        }
    });

    assert_eq!(result, Ok(()));
    assert_eq!(calls, 5);
    assert_eq!(sleeper.sleeps, vec![10, 20, 25, 25]);
}

#[test]
fn permanent_errors_return_without_retrying() {
    let config = RetryConfig::new(5, 10, 100);
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;

    let result = run_job(&config, &mut sleeper, || {
        calls += 1;
        Err(RetryError::Permanent("invalid input".into()))
    });

    assert_eq!(result, Err(RetryError::Permanent("invalid input".into())));
    assert_eq!(calls, 1);
    assert!(sleeper.sleeps.is_empty());
}

#[test]
fn max_attempts_includes_first_call_and_exhaustion_returns_last_error() {
    let config = RetryConfig::new(3, 1, 100);
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;

    let result = run_job(&config, &mut sleeper, || {
        calls += 1;
        Err(RetryError::Transient(format!("attempt {calls}")))
    });

    assert_eq!(result, Err(RetryError::Transient("attempt 3".into())));
    assert_eq!(calls, 3);
    assert_eq!(sleeper.sleeps, vec![1, 2]);
}

#[test]
fn zero_attempt_budget_still_makes_one_call() {
    let config = RetryConfig::new(0, 10, 100);
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;

    let result = run_job(&config, &mut sleeper, || {
        calls += 1;
        Err(RetryError::Transient("temporary".into()))
    });

    assert!(result.is_err());
    assert_eq!(calls, 1);
    assert!(sleeper.sleeps.is_empty());
}
